class Solution {
public:
    int numberOfSpecialSubstrings(string s) {
        vector<int> last(256, -1);
        int left = 0, answer = 0;
        for (int right = 0; right < (int)s.size(); ++right) {
            unsigned char c = s[right];
            left = max(left, last[c] + 1);
            answer += right - left + 1;
            last[c] = right;
        }
        return answer;
    }
};
